const draw = () => {
  ctx.clearRect(0, 0, canvas.width, canvas.height);
  // Background stars
  ctx.fillStyle = '#fff';
  stars.forEach(s => {
    ctx.beginPath();
    ctx.arc(s.x, s.y, s.r, 0, Math.PI * 2);
    ctx.fill();
  });
  // Ship as triangle
  ctx.fillStyle = ship.color;
  ctx.beginPath();
  ctx.moveTo(ship.x + ship.width / 2, ship.y);
  ctx.lineTo(ship.x, ship.y + ship.height);
  ctx.lineTo(ship.x + ship.width, ship.y + ship.height);
  ctx.closePath();
  ctx.fill();
  // Asteroids with gradient
  asteroids.forEach(a => {
    const grad = ctx.createRadialGradient(a.x, a.y, a.r * 0.2, a.x, a.y, a.r);
    grad.addColorStop(0, '#777');
    grad.addColorStop(1, '#333');
    ctx.fillStyle = grad;
    ctx.beginPath();
    ctx.arc(a.x, a.y, a.r, 0, Math.PI * 2);
    ctx.fill();
  });
  // Fuel pickups (glowing)
  fuels.forEach(f => {
    const glow = ctx.createRadialGradient(f.x, f.y, 0, f.x, f.y, f.r);
    glow.addColorStop(0, '#0f0');
    glow.addColorStop(1, '#030');
    ctx.fillStyle = glow;
    ctx.beginPath();
    ctx.arc(f.x, f.y, f.r, 0, Math.PI * 2);
    ctx.fill();
  });
  // Fuel bar
  ctx.fillStyle = '#ff0';
  ctx.fillRect(10, 10, ship.fuel * 2, 10);
  ctx.strokeStyle = '#000';
  ctx.strokeRect(10, 10, 200, 10);
};

